// This is the updated BookingForm component section for BanquetModule.js
// Replace the existing BookingForm component in your BanquetModule.js with this:

const BookingForm = ({ venues, packages, onCancel }) => {
  const [formData, setFormData] = useState({
    customerName: '',
    phone: '',
    email: '',
    eventDate: '',
    eventTime: '',
    venueId: '',
    packageId: '',
    numberOfGuests: '',
    advanceAmount: '',
    specialRequests: '',
    decorationRequired: false,
    djRequired: false
  });

  // Function to check if all mandatory fields are filled
  const isFormValid = () => {
    const mandatoryFields = [
      'customerName',
      'phone',
      'eventDate',
      'eventTime',
      'venueId',
      'packageId',
      'numberOfGuests'
    ];

    // Check if all mandatory fields have values
    return mandatoryFields.every(field => {
      const value = formData[field];
      // Check for non-empty strings and valid selections
      return value !== '' && value !== null && value !== undefined && String(value).trim() !== '';
    });
  };

  // Also validate phone number format
  const isPhoneValid = () => {
    const phoneRegex = /^[0-9]{10}$/;
    return phoneRegex.test(formData.phone);
  };

  // Email validation (if provided)
  const isEmailValid = () => {
    if (!formData.email) return true; // Email is optional
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(formData.email);
  };

  // Combined validation
  const canSubmit = () => {
    return isFormValid() && isPhoneValid() && isEmailValid();
  };

  const calculateTotal = () => {
    if (!formData.packageId || !formData.numberOfGuests) return 0;
    const selectedPackage = packages.find(p => p.id === parseInt(formData.packageId));
    if (!selectedPackage) return 0;

    const baseAmount = selectedPackage.pricePerPerson * parseInt(formData.numberOfGuests);
    const decorationCost = formData.decorationRequired ? 5000 : 0;
    const djCost = formData.djRequired ? 8000 : 0;

    return baseAmount + decorationCost + djCost;
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    // Double-check validation before submission
    if (!canSubmit()) {
      alert('Please fill all mandatory fields correctly before submitting.');
      return;
    }

    const newBooking = {
      id: Date.now(),
      ...formData,
      venueId: parseInt(formData.venueId),
      packageId: parseInt(formData.packageId),
      numberOfGuests: parseInt(formData.numberOfGuests),
      advanceAmount: parseFloat(formData.advanceAmount || 0),
      totalAmount: calculateTotal(),
      status: 'confirmed',
      createdAt: new Date().toISOString()
    };

    setBookings([...bookings, newBooking]);
    setShowBookingForm(false);
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-lg p-6 w-full max-w-2xl max-h-[90vh] overflow-y-auto">
        <h3 className="text-lg font-semibold mb-4">New Booking</h3>
        <form onSubmit={handleSubmit} className="space-y-4">
          {/* Customer Information */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Customer Name <span className="text-red-500">*</span>
              </label>
              <input
                type="text"
                value={formData.customerName}
                onChange={(e) => setFormData({...formData, customerName: e.target.value})}
                className={`w-full border rounded-md px-3 py-2 ${
                  formData.customerName ? 'border-gray-300' : 'border-red-300'
                }`}
                placeholder="Enter customer name"
                required
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Phone Number <span className="text-red-500">*</span>
              </label>
              <input
                type="tel"
                value={formData.phone}
                onChange={(e) => setFormData({...formData, phone: e.target.value})}
                className={`w-full border rounded-md px-3 py-2 ${
                  formData.phone && !isPhoneValid()
                    ? 'border-red-300'
                    : formData.phone
                    ? 'border-gray-300'
                    : 'border-red-300'
                }`}
                placeholder="10-digit phone number"
                maxLength="10"
                required
              />
              {formData.phone && !isPhoneValid() && (
                <p className="text-red-500 text-xs mt-1">Please enter a valid 10-digit phone number</p>
              )}
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Email Address
            </label>
            <input
              type="email"
              value={formData.email}
              onChange={(e) => setFormData({...formData, email: e.target.value})}
              className={`w-full border rounded-md px-3 py-2 ${
                formData.email && !isEmailValid()
                  ? 'border-red-300'
                  : 'border-gray-300'
              }`}
              placeholder="customer@email.com (optional)"
            />
            {formData.email && !isEmailValid() && (
              <p className="text-red-500 text-xs mt-1">Please enter a valid email address</p>
            )}
          </div>

          {/* Event Details */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Event Date <span className="text-red-500">*</span>
              </label>
              <input
                type="date"
                value={formData.eventDate}
                onChange={(e) => setFormData({...formData, eventDate: e.target.value})}
                min={new Date().toISOString().split('T')[0]}
                className={`w-full border rounded-md px-3 py-2 ${
                  formData.eventDate ? 'border-gray-300' : 'border-red-300'
                }`}
                required
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Event Time <span className="text-red-500">*</span>
              </label>
              <input
                type="time"
                value={formData.eventTime}
                onChange={(e) => setFormData({...formData, eventTime: e.target.value})}
                className={`w-full border rounded-md px-3 py-2 ${
                  formData.eventTime ? 'border-gray-300' : 'border-red-300'
                }`}
                required
              />
            </div>
          </div>

          {/* Venue and Package */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Select Venue <span className="text-red-500">*</span>
              </label>
              <select
                value={formData.venueId}
                onChange={(e) => setFormData({...formData, venueId: e.target.value})}
                className={`w-full border rounded-md px-3 py-2 ${
                  formData.venueId ? 'border-gray-300' : 'border-red-300'
                }`}
                required
              >
                <option value="">Choose a venue</option>
                {venues.map(venue => (
                  <option key={venue.id} value={venue.id}>
                    {venue.name} (Capacity: {venue.capacity})
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Select Package <span className="text-red-500">*</span>
              </label>
              <select
                value={formData.packageId}
                onChange={(e) => setFormData({...formData, packageId: e.target.value})}
                className={`w-full border rounded-md px-3 py-2 ${
                  formData.packageId ? 'border-gray-300' : 'border-red-300'
                }`}
                required
              >
                <option value="">Choose a package</option>
                {packages.map(pkg => (
                  <option key={pkg.id} value={pkg.id}>
                    {pkg.name} - ₹{pkg.pricePerPerson}/person
                  </option>
                ))}
              </select>
            </div>
          </div>

          {/* Guest Count and Advance */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Number of Guests <span className="text-red-500">*</span>
              </label>
              <input
                type="number"
                value={formData.numberOfGuests}
                onChange={(e) => setFormData({...formData, numberOfGuests: e.target.value})}
                className={`w-full border rounded-md px-3 py-2 ${
                  formData.numberOfGuests ? 'border-gray-300' : 'border-red-300'
                }`}
                min="1"
                placeholder="Enter number of guests"
                required
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Advance Amount (₹)
              </label>
              <input
                type="number"
                value={formData.advanceAmount}
                onChange={(e) => setFormData({...formData, advanceAmount: e.target.value})}
                className="w-full border border-gray-300 rounded-md px-3 py-2"
                min="0"
                placeholder="Enter advance amount"
              />
            </div>
          </div>

          {/* Additional Services */}
          <div className="space-y-2">
            <label className="block text-sm font-medium text-gray-700">Additional Services</label>
            <div className="flex space-x-6">
              <label className="flex items-center">
                <input
                  type="checkbox"
                  checked={formData.decorationRequired}
                  onChange={(e) => setFormData({...formData, decorationRequired: e.target.checked})}
                  className="mr-2"
                />
                <span className="text-sm">Decoration (+₹5,000)</span>
              </label>
              <label className="flex items-center">
                <input
                  type="checkbox"
                  checked={formData.djRequired}
                  onChange={(e) => setFormData({...formData, djRequired: e.target.checked})}
                  className="mr-2"
                />
                <span className="text-sm">DJ Services (+₹8,000)</span>
              </label>
            </div>
          </div>

          {/* Special Requests */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Special Requests
            </label>
            <textarea
              value={formData.specialRequests}
              onChange={(e) => setFormData({...formData, specialRequests: e.target.value})}
              className="w-full border border-gray-300 rounded-md px-3 py-2"
              rows="3"
              placeholder="Any special requirements or requests..."
            />
          </div>

          {/* Total Amount Display */}
          {formData.packageId && formData.numberOfGuests && (
            <div className="bg-blue-50 p-4 rounded-lg">
              <div className="flex justify-between items-center">
                <span className="text-lg font-medium text-gray-700">Estimated Total:</span>
                <span className="text-2xl font-bold text-blue-600">₹{calculateTotal().toLocaleString()}</span>
              </div>
            </div>
          )}

          {/* Validation Message */}
          {!canSubmit() && (
            <div className="bg-yellow-50 border border-yellow-200 text-yellow-700 px-4 py-3 rounded-lg text-sm">
              Please fill all mandatory fields marked with * to create the booking.
            </div>
          )}

          {/* Form Actions */}
          <div className="flex justify-end space-x-3 pt-4">
            <button
              type="button"
              onClick={onCancel}
              className="px-4 py-2 text-gray-700 border border-gray-300 rounded-md hover:bg-gray-50"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={!canSubmit()}
              className={`px-4 py-2 rounded-md text-white font-medium ${
                canSubmit()
                  ? 'bg-blue-500 hover:bg-blue-600 cursor-pointer'
                  : 'bg-gray-300 cursor-not-allowed opacity-50'
              }`}
            >
              Create Booking
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};
